    pg.click('a[aria-label="Математика 7: ашу"]'); pg.wait_for_selector('h1:text-is("Математика 7")')
    ok('C3 "Ашу" opens a separate course page (#course/id) with the course title and its own empty state', pg.evaluate('location.hash').startswith('#course/') and pg.locator('text=Бұл курста модуль жоқ').count()==1 and pg.locator('main a:text-is("Курстар")').count()==1)
    ok('C3 courses tab stays current on the course page', pg.locator('nav[aria-label="Сабақтар бөлімдері"] a[aria-current=page]').inner_text().strip()=='Курстар')
